package clusterdata.datatypes;

public class TaskEvent {
    public long timestamp;
    public String missingInfo;
    public long jobId;
    public long taskIndex;
    public String machineId;
    public int eventType;
    public String user;
    public int schedulingClass;
    public int priority;
    public double cpuRequest;
    public double memoryRequest;
    public double diskRequest;
    public int differentMachinesRestriction;

    public TaskEvent() {}

    public TaskEvent(long timestamp, String missingInfo, long jobId, long taskIndex,
                     String machineId, int eventType, String user, int schedulingClass,
                     int priority, double cpuRequest, double memoryRequest,
                     double diskRequest, int differentMachinesRestriction) {
        this.timestamp = timestamp;
        this.missingInfo = missingInfo;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.machineId = machineId;
        this.eventType = eventType;
        this.user = user;
        this.schedulingClass = schedulingClass;
        this.priority = priority;
        this.cpuRequest = cpuRequest;
        this.memoryRequest = memoryRequest;
        this.diskRequest = diskRequest;
        this.differentMachinesRestriction = differentMachinesRestriction;
    }

    public static TaskEvent fromCsvLine(String line) {
        String[] fields = line.split(",", -1);

        TaskEvent event = new TaskEvent();
        event.timestamp = Long.parseLong(fields[0]);
        event.missingInfo = fields[1];
        event.jobId = Long.parseLong(fields[2]);
        event.taskIndex = fields[3].isEmpty() ? 0 : Long.parseLong(fields[3]);
        event.machineId = fields[4];
        event.eventType = fields[5].isEmpty() ? -1 : Integer.parseInt(fields[5]);
        event.user = fields[6];
        event.schedulingClass = fields[7].isEmpty() ? 0 : Integer.parseInt(fields[7]);
        event.priority = fields[8].isEmpty() ? 0 : Integer.parseInt(fields[8]);
        event.cpuRequest = fields[9].isEmpty() ? 0.0 : Double.parseDouble(fields[9]);
        event.memoryRequest = fields[10].isEmpty() ? 0.0 : Double.parseDouble(fields[10]);
        event.diskRequest = fields[11].isEmpty() ? 0.0 : Double.parseDouble(fields[11]);
        event.differentMachinesRestriction = fields[12].isEmpty() ? 0 : Integer.parseInt(fields[12]);

        return event;
    }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "timestamp=" + timestamp +
                ", jobId=" + jobId +
                ", taskIndex=" + taskIndex +
                ", eventType=" + eventType +
                '}';
    }
}

