package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.AggregateFunction;
import org.apache.flink.api.common.functions.CoGroupFunction;
import org.apache.flink.api.common.serialization.SimpleStringEncoder;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.MemorySize;
import org.apache.flink.connector.file.sink.FileSink;
import org.apache.flink.core.fs.Path;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.datastream.KeyedStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.time.Duration;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Create task event source
        SourceFunction<TaskEvent> taskSource = new GzipCsvTaskSource(taskInput);
        DataStream<TaskEvent> taskEvents = env.addSource(taskSourceOrTest(taskSource));

        // Create job event source
        SourceFunction<JobEvent> jobSource = new GzipCsvJobSource(jobInput);
        DataStream<JobEvent> jobEvents = env.addSource(jobSourceOrTest(jobSource));

        // Filter for SUBMIT events only (eventType == 0)
        DataStream<TaskEvent> submitEvents = taskEvents
                .filter(event -> event.eventType == 0)
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, timestamp) -> event.timestamp / 1000) // Convert microseconds to milliseconds
                );

        // Group by job ID and create sessions with 10-minute gap
        // 10 minutes = 600 seconds = 600,000 milliseconds
        KeyedStream<TaskEvent, Long> keyedSubmits = submitEvents.keyBy(event -> event.jobId);

        // Apply session windows and count tasks in each session
        DataStream<Tuple2<Long, Long>> sessionCounts = keyedSubmits
                .window(EventTimeSessionWindows.withGap(Time.milliseconds(600000)))
                .aggregate(new CountAggregator(), new SessionWindowProcessor());

        // Keep track of maximum session size per job
        DataStream<Tuple2<Long, Long>> maxPerJob = sessionCounts
                .keyBy(tuple -> tuple.f0)
                .process(new MaxSessionTracker());

        // Filter for FINISH events (eventType == 4) from job events
        DataStream<JobEvent> finishedJobs = jobEvents
                .filter(event -> event.eventType == 4)
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, timestamp) -> event.timestamp / 1000)
                );

        // Join with finished jobs to output only when job is done
        DataStream<String> output = maxPerJob
                .keyBy(tuple -> tuple.f0)
                .connect(finishedJobs.keyBy(event -> event.jobId))
                .flatMap(new JobFinishCoMapper());

        // Write output to file
        FileSink<String> sink = FileSink
                .forRowFormat(new Path(outputPath), new SimpleStringEncoder<String>("UTF-8"))
                .withRollingPolicy(
                        org.apache.flink.connector.file.sink.rolling.OnCheckpointRollingPolicy.build()
                )
                .withBucketCheckInterval(1000)
                .build();

        output.sinkTo(sinkOrTest(sink));

        env.execute("LongestSessionPerJob");
    }

    // Aggregate function to count tasks in a session
    static class CountAggregator implements AggregateFunction<TaskEvent, Long, Long> {
        @Override
        public Long createAccumulator() {
            return 0L;
        }

        @Override
        public Long add(TaskEvent value, Long accumulator) {
            return accumulator + 1;
        }

        @Override
        public Long getResult(Long accumulator) {
            return accumulator;
        }

        @Override
        public Long merge(Long a, Long b) {
            return a + b;
        }
    }

    // Process window function to emit jobId and count
    static class SessionWindowProcessor extends ProcessWindowFunction<Long, Tuple2<Long, Long>, Long, TimeWindow> {
        @Override
        public void process(Long jobId, Context context, Iterable<Long> elements, Collector<Tuple2<Long, Long>> out) {
            Long count = elements.iterator().next();
            out.collect(new Tuple2<>(jobId, count));
        }
    }

    // Track maximum session size per job
    static class MaxSessionTracker extends org.apache.flink.streaming.api.functions.KeyedProcessFunction<Long, Tuple2<Long, Long>, Tuple2<Long, Long>> {
        private transient org.apache.flink.api.common.state.ValueState<Long> maxState;

        @Override
        public void open(org.apache.flink.configuration.Configuration parameters) {
            maxState = getRuntimeContext().getState(
                    new org.apache.flink.api.common.state.ValueStateDescriptor<>("max", Long.class)
            );
        }

        @Override
        public void processElement(Tuple2<Long, Long> value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            Long currentMax = maxState.value();
            if (currentMax == null || value.f1 > currentMax) {
                maxState.update(value.f1);
                out.collect(value);
            }
        }
    }

    // Co-map to output only when job finishes
    static class JobFinishCoMapper extends org.apache.flink.streaming.api.functions.co.RichCoFlatMapFunction<Tuple2<Long, Long>, JobEvent, String> {
        private transient org.apache.flink.api.common.state.ValueState<Long> maxCountState;
        private transient org.apache.flink.api.common.state.ValueState<Boolean> finishedState;

        @Override
        public void open(org.apache.flink.configuration.Configuration parameters) {
            maxCountState = getRuntimeContext().getState(
                    new org.apache.flink.api.common.state.ValueStateDescriptor<>("maxCount", Long.class)
            );
            finishedState = getRuntimeContext().getState(
                    new org.apache.flink.api.common.state.ValueStateDescriptor<>("finished", Boolean.class)
            );
        }

        @Override
        public void flatMap1(Tuple2<Long, Long> value, Collector<String> out) throws Exception {
            // Update max count
            maxCountState.update(value.f1);

            // If job already finished, output immediately
            Boolean finished = finishedState.value();
            if (finished != null && finished) {
                out.collect("(" + value.f0 + "," + value.f1 + ")");
            }
        }

        @Override
        public void flatMap2(JobEvent value, Collector<String> out) throws Exception {
            // Mark job as finished
            finishedState.update(true);

            // Output if we have a max count
            Long maxCount = maxCountState.value();
            if (maxCount != null) {
                out.collect("(" + value.jobId + "," + maxCount + ")");
            } else {
                // No sessions found, output 0
                out.collect("(" + value.jobId + ",0)");
            }
        }
    }

    // Source function for reading gzipped CSV task events
    static class GzipCsvTaskSource implements SourceFunction<TaskEvent> {
        private final String filePath;
        private volatile boolean running = true;

        public GzipCsvTaskSource(String filePath) {
            this.filePath = filePath;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            try (BufferedReader reader = new BufferedReader(
                    new InputStreamReader(new GZIPInputStream(new FileInputStream(filePath))))) {
                String line;
                while (running && (line = reader.readLine()) != null) {
                    try {
                        TaskEvent event = TaskEvent.fromCsvLine(line);
                        ctx.collect(event);
                    } catch (Exception e) {
                        // Skip malformed lines
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    // Source function for reading gzipped CSV job events
    static class GzipCsvJobSource implements SourceFunction<JobEvent> {
        private final String filePath;
        private volatile boolean running = true;

        public GzipCsvJobSource(String filePath) {
            this.filePath = filePath;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            try (BufferedReader reader = new BufferedReader(
                    new InputStreamReader(new GZIPInputStream(new FileInputStream(filePath))))) {
                String line;
                while (running && (line = reader.readLine()) != null) {
                    try {
                        JobEvent event = JobEvent.fromCsvLine(line);
                        ctx.collect(event);
                    } catch (Exception e) {
                        // Skip malformed lines
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }
}

